-- ITR Intake: initial schema (Stage 5.1).
--
-- Conventions
--   * Every table is STRICT (column types are enforced).
--   * Internal IDs are UUID4 text (36 characters), generated by the application.
--   * Timestamps are UTC ISO-8601 text ending in "Z" (written by the application).
--   * Money is decimal text, never REAL: digits with an optional fraction, and a
--     leading "-" only where a value may be negative (balances).
--   * Ownership: every case-scoped row carries firm_id and references
--     cases(id, firm_id), so a row can never belong to one case but another firm.
--     Likewise sessions, cases and firm-code usage reference (id, firm_id) pairs.
--   * Children of a case are deleted with it; firms, users and audit history are
--     never deleted implicitly (NO ACTION).
--
-- This migration is applied inside a transaction by the runner; it must not
-- contain BEGIN/COMMIT itself.

-- Firms ---------------------------------------------------------------------

CREATE TABLE firms (
    id                  TEXT PRIMARY KEY CHECK (length(id) = 36),
    name                TEXT NOT NULL CHECK (length(trim(name)) > 0),
    contact_phone       TEXT,
    contact_address     TEXT,
    registration_number TEXT CHECK (registration_number IS NULL OR length(trim(registration_number)) > 0),
    status              TEXT NOT NULL DEFAULT 'pending_verification'
                        CHECK (status IN ('pending_verification', 'pending_approval', 'active', 'suspended')),
    approved_at         TEXT CHECK (approved_at IS NULL OR approved_at LIKE '____-__-__T__:__:__%Z'),
    approved_by         TEXT,
    created_at          TEXT NOT NULL CHECK (created_at LIKE '____-__-__T__:__:__%Z'),
    updated_at          TEXT NOT NULL CHECK (updated_at LIKE '____-__-__T__:__:__%Z'),
    CHECK (status <> 'active' OR approved_at IS NOT NULL)
) STRICT;

-- Professional details are self-declared and unverified; a duplicate
-- registration number is refused outright.
CREATE UNIQUE INDEX firms_registration_number_uq
    ON firms (registration_number) WHERE registration_number IS NOT NULL;

-- CA users --------------------------------------------------------------------

CREATE TABLE ca_users (
    id                TEXT PRIMARY KEY CHECK (length(id) = 36),
    firm_id           TEXT NOT NULL REFERENCES firms (id),
    email_norm        TEXT NOT NULL UNIQUE
                      CHECK (email_norm = lower(trim(email_norm)) AND email_norm LIKE '%_@_%'),
    full_name         TEXT NOT NULL CHECK (length(trim(full_name)) > 0),
    password_hash     TEXT NOT NULL CHECK (length(password_hash) > 0),
    email_verified_at TEXT CHECK (email_verified_at IS NULL OR email_verified_at LIKE '____-__-__T__:__:__%Z'),
    status            TEXT NOT NULL DEFAULT 'pending' CHECK (status IN ('pending', 'active', 'disabled')),
    role              TEXT NOT NULL DEFAULT 'owner' CHECK (role IN ('owner', 'member')),
    failed_logins     INTEGER NOT NULL DEFAULT 0 CHECK (failed_logins >= 0),
    locked_until      TEXT CHECK (locked_until IS NULL OR locked_until LIKE '____-__-__T__:__:__%Z'),
    created_at        TEXT NOT NULL CHECK (created_at LIKE '____-__-__T__:__:__%Z'),
    updated_at        TEXT NOT NULL CHECK (updated_at LIKE '____-__-__T__:__:__%Z'),
    UNIQUE (id, firm_id)
) STRICT;

CREATE INDEX ca_users_firm_idx ON ca_users (firm_id);

-- Firm codes --------------------------------------------------------------------
-- A firm code identifies a firm to new clients; it never authenticates anyone.

CREATE TABLE firm_codes (
    id         TEXT PRIMARY KEY CHECK (length(id) = 36),
    firm_id    TEXT NOT NULL REFERENCES firms (id),
    code       TEXT NOT NULL UNIQUE
               CHECK (length(code) BETWEEN 8 AND 32 AND code NOT GLOB '*[^0-9A-Z]*'),
    status     TEXT NOT NULL DEFAULT 'active' CHECK (status IN ('active', 'revoked')),
    created_at TEXT NOT NULL CHECK (created_at LIKE '____-__-__T__:__:__%Z'),
    revoked_at TEXT CHECK (revoked_at IS NULL OR revoked_at LIKE '____-__-__T__:__:__%Z'),
    CHECK ((status = 'revoked') = (revoked_at IS NOT NULL)),
    UNIQUE (id, firm_id)
) STRICT;

-- At most one active code per firm.
CREATE UNIQUE INDEX firm_codes_one_active_uq ON firm_codes (firm_id) WHERE status = 'active';

-- Client identities ---------------------------------------------------------------
-- Scoped to one firm: the same e-mail at two firms is two unrelated identities.

CREATE TABLE client_identities (
    id                TEXT PRIMARY KEY CHECK (length(id) = 36),
    firm_id           TEXT NOT NULL REFERENCES firms (id),
    email_norm        TEXT NOT NULL CHECK (email_norm = lower(trim(email_norm)) AND email_norm LIKE '%_@_%'),
    email_verified_at TEXT CHECK (email_verified_at IS NULL OR email_verified_at LIKE '____-__-__T__:__:__%Z'),
    created_at        TEXT NOT NULL CHECK (created_at LIKE '____-__-__T__:__:__%Z'),
    UNIQUE (firm_id, email_norm),
    UNIQUE (id, firm_id)
) STRICT;

-- Verification challenges -------------------------------------------------------
-- One-time codes and tokens. Only a hash of the secret is stored.

CREATE TABLE verification_challenges (
    id           TEXT PRIMARY KEY CHECK (length(id) = 36),
    purpose      TEXT NOT NULL CHECK (purpose IN ('client_login', 'ca_email_verification', 'ca_password_reset')),
    firm_id      TEXT REFERENCES firms (id),
    ca_user_id   TEXT REFERENCES ca_users (id) ON DELETE CASCADE,
    subject      TEXT NOT NULL CHECK (length(subject) > 0),
    secret_hash  TEXT NOT NULL CHECK (length(secret_hash) = 64 AND secret_hash NOT GLOB '*[^0-9a-f]*'),
    attempts     INTEGER NOT NULL DEFAULT 0 CHECK (attempts >= 0),
    max_attempts INTEGER NOT NULL CHECK (max_attempts > 0),
    expires_at   TEXT NOT NULL CHECK (expires_at LIKE '____-__-__T__:__:__%Z'),
    consumed_at  TEXT CHECK (consumed_at IS NULL OR consumed_at LIKE '____-__-__T__:__:__%Z'),
    created_at   TEXT NOT NULL CHECK (created_at LIKE '____-__-__T__:__:__%Z'),
    CHECK (attempts <= max_attempts),
    CHECK (purpose <> 'client_login' OR (firm_id IS NOT NULL AND ca_user_id IS NULL)),
    CHECK (purpose = 'client_login' OR ca_user_id IS NOT NULL)
) STRICT;

CREATE INDEX verification_challenges_lookup_idx
    ON verification_challenges (purpose, subject, created_at);

-- Sessions ------------------------------------------------------------------------
-- Server-side sessions; only a SHA-256 hash of the token is stored.

CREATE TABLE sessions (
    id                  TEXT PRIMARY KEY CHECK (length(id) = 36),
    token_hash          TEXT NOT NULL UNIQUE CHECK (length(token_hash) = 64 AND token_hash NOT GLOB '*[^0-9a-f]*'),
    kind                TEXT NOT NULL CHECK (kind IN ('ca', 'client')),
    firm_id             TEXT NOT NULL REFERENCES firms (id),
    ca_user_id          TEXT,
    client_identity_id  TEXT,
    created_at          TEXT NOT NULL CHECK (created_at LIKE '____-__-__T__:__:__%Z'),
    last_seen_at        TEXT NOT NULL CHECK (last_seen_at LIKE '____-__-__T__:__:__%Z'),
    idle_expires_at     TEXT NOT NULL CHECK (idle_expires_at LIKE '____-__-__T__:__:__%Z'),
    absolute_expires_at TEXT NOT NULL CHECK (absolute_expires_at LIKE '____-__-__T__:__:__%Z'),
    revoked_at          TEXT CHECK (revoked_at IS NULL OR revoked_at LIKE '____-__-__T__:__:__%Z'),
    CHECK ((kind = 'ca' AND ca_user_id IS NOT NULL AND client_identity_id IS NULL)
        OR (kind = 'client' AND client_identity_id IS NOT NULL AND ca_user_id IS NULL)),
    -- The session's firm must be the user's firm.
    FOREIGN KEY (ca_user_id, firm_id) REFERENCES ca_users (id, firm_id) ON DELETE CASCADE,
    FOREIGN KEY (client_identity_id, firm_id) REFERENCES client_identities (id, firm_id) ON DELETE CASCADE
) STRICT;

CREATE INDEX sessions_expiry_idx ON sessions (absolute_expires_at);

-- Rate limits ---------------------------------------------------------------------
-- Fixed-window counters, e.g. bucket 'otp:email:<hash>'. Keys hold hashes, not raw values.

CREATE TABLE rate_limits (
    bucket       TEXT NOT NULL CHECK (length(bucket) > 0),
    window_start TEXT NOT NULL CHECK (window_start LIKE '____-__-__T__:__:__%Z'),
    count        INTEGER NOT NULL CHECK (count >= 0),
    PRIMARY KEY (bucket, window_start)
) STRICT, WITHOUT ROWID;

-- Cases ---------------------------------------------------------------------------

CREATE TABLE cases (
    id                       TEXT PRIMARY KEY CHECK (length(id) = 36),
    firm_id                  TEXT NOT NULL REFERENCES firms (id),
    client_identity_id       TEXT NOT NULL,
    reference                TEXT NOT NULL UNIQUE
                             CHECK (reference GLOB 'IT-*' AND reference NOT GLOB '*[^0-9A-Z-]*'),
    financial_year           TEXT NOT NULL CHECK (financial_year GLOB '[0-9][0-9][0-9][0-9]-[0-9][0-9]'),
    client_first_name        TEXT NOT NULL CHECK (length(trim(client_first_name)) > 0),
    profile_json             TEXT NOT NULL DEFAULT '{}' CHECK (json_valid(profile_json)),
    status                   TEXT NOT NULL DEFAULT 'draft'
                             CHECK (status IN ('draft', 'statement_uploaded', 'processing', 'questions_in_progress',
                                               'documents_pending', 'submitted', 'ca_review_required',
                                               'review_ready', 'closed')),
    created_via_firm_code_id TEXT,
    opening_balance          TEXT CHECK (opening_balance IS NULL OR (opening_balance GLOB '*[0-9]*'
                                         AND ltrim(opening_balance, '-') NOT GLOB '*[^0-9.]*'
                                         AND opening_balance NOT GLOB '?*-*' AND opening_balance NOT GLOB '*.*.*')),
    closing_balance          TEXT CHECK (closing_balance IS NULL OR (closing_balance GLOB '*[0-9]*'
                                         AND ltrim(closing_balance, '-') NOT GLOB '*[^0-9.]*'
                                         AND closing_balance NOT GLOB '?*-*' AND closing_balance NOT GLOB '*.*.*')),
    period_start             TEXT CHECK (period_start IS NULL OR period_start GLOB '[0-9][0-9][0-9][0-9]-[0-9][0-9]-[0-9][0-9]'),
    period_end               TEXT CHECK (period_end IS NULL OR period_end GLOB '[0-9][0-9][0-9][0-9]-[0-9][0-9]-[0-9][0-9]'),
    classifier_version       TEXT,
    -- Persisted workflow state (Stage 4 IntakeContext): the pending question
    -- lives in `questions`; history and confirmations in their own tables.
    stopped_reason           TEXT CHECK (stopped_reason IS NULL OR stopped_reason IN
                                         ('turn_cap_reached', 'model_no_further_question', 'nothing_left_to_ask')),
    questions_issued         INTEGER NOT NULL DEFAULT 0 CHECK (questions_issued >= 0),
    version                  INTEGER NOT NULL DEFAULT 1 CHECK (version >= 1),
    generation_lease_until   TEXT CHECK (generation_lease_until IS NULL OR generation_lease_until LIKE '____-__-__T__:__:__%Z'),
    created_at               TEXT NOT NULL CHECK (created_at LIKE '____-__-__T__:__:__%Z'),
    updated_at               TEXT NOT NULL CHECK (updated_at LIKE '____-__-__T__:__:__%Z'),
    closed_at                TEXT CHECK (closed_at IS NULL OR closed_at LIKE '____-__-__T__:__:__%Z'),
    CHECK ((status = 'closed') = (closed_at IS NOT NULL)),
    UNIQUE (id, firm_id),
    -- The client identity and the firm code used must belong to the case's firm.
    FOREIGN KEY (client_identity_id, firm_id) REFERENCES client_identities (id, firm_id),
    FOREIGN KEY (created_via_firm_code_id, firm_id) REFERENCES firm_codes (id, firm_id)
) STRICT;

-- One open case per client identity, firm and financial year. A closed case
-- drops out of the index, so a new case may be opened after closing.
CREATE UNIQUE INDEX cases_one_open_per_client_year_uq
    ON cases (firm_id, client_identity_id, financial_year) WHERE status <> 'closed';
CREATE INDEX cases_firm_status_idx ON cases (firm_id, status, updated_at);
CREATE INDEX cases_client_idx ON cases (client_identity_id);

-- Statement rows ------------------------------------------------------------------
-- The extracted rows (raw text, kept exactly) and the classifier's result.

CREATE TABLE statement_rows (
    case_id               TEXT NOT NULL,
    firm_id               TEXT NOT NULL,
    row_number            INTEGER NOT NULL CHECK (row_number > 0),
    raw_date              TEXT,
    raw_narration         TEXT,
    raw_debit             TEXT,
    raw_credit            TEXT,
    raw_balance           TEXT,
    is_valid              INTEGER NOT NULL CHECK (is_valid IN (0, 1)),
    issues_json           TEXT NOT NULL DEFAULT '[]' CHECK (json_valid(issues_json) AND json_type(issues_json) = 'array'),
    txn_date              TEXT CHECK (txn_date IS NULL OR txn_date GLOB '[0-9][0-9][0-9][0-9]-[0-9][0-9]-[0-9][0-9]'),
    narration             TEXT,
    debit                 TEXT CHECK (debit IS NULL OR (debit GLOB '*[0-9]*' AND debit NOT GLOB '*[^0-9.]*'
                                      AND debit NOT GLOB '*.*.*')),
    credit                TEXT CHECK (credit IS NULL OR (credit GLOB '*[0-9]*' AND credit NOT GLOB '*[^0-9.]*'
                                      AND credit NOT GLOB '*.*.*')),
    balance               TEXT CHECK (balance IS NULL OR (balance GLOB '*[0-9]*' AND ltrim(balance, '-') NOT GLOB '*[^0-9.]*'
                                      AND balance NOT GLOB '?*-*' AND balance NOT GLOB '*.*.*')),
    mode                  TEXT,
    counterparty          TEXT,
    category              TEXT CHECK (category IS NULL OR category IN (
                              'Salary / Pension', 'Business / Professional Receipts', 'Rent Received',
                              'Interest – Savings Bank', 'Interest – FD / RD / Others', 'Dividend',
                              'Sale / Redemption of Investments', 'Income Tax Refund',
                              'Loans Received / Repayment of Loans Given', 'Gifts / Receipts from Non-relatives',
                              'Investments – Tax-saving', 'Investments – Others', 'Insurance – Health',
                              'Loan EMI / Repayment', 'Loans Given', 'Tax Payments', 'Donations',
                              'Credit Card Payments', 'Rent Paid', 'Business / Professional Expenses',
                              'Self Transfer', 'Family Transfer', 'Cash Withdrawal', 'Cash Deposit',
                              'Personal Expenses', 'Bank Charges', 'Reversals / Refunds', 'Others – Needs Review')),
    confidence            TEXT CHECK (confidence IS NULL OR confidence IN ('high', 'medium', 'low')),
    review_status         TEXT CHECK (review_status IS NULL OR review_status IN
                                      ('Auto-classified', 'Needs confirmation', 'Needs review')),
    matched_rule          TEXT,
    flags_json            TEXT NOT NULL DEFAULT '[]' CHECK (json_valid(flags_json) AND json_type(flags_json) = 'array'),
    classification_reason TEXT,
    classifier_version    TEXT,
    -- A valid row has its parsed facts; an invalid row has no classification.
    CHECK (is_valid = 0 OR (txn_date IS NOT NULL AND narration IS NOT NULL AND debit IS NOT NULL AND credit IS NOT NULL)),
    CHECK (is_valid = 1 OR (category IS NULL AND matched_rule IS NULL)),
    PRIMARY KEY (case_id, row_number),
    FOREIGN KEY (case_id, firm_id) REFERENCES cases (id, firm_id) ON DELETE CASCADE
) STRICT, WITHOUT ROWID;

-- Questions and answers ---------------------------------------------------------------
-- One row per issued question; the answer is stored on the same row.

CREATE TABLE questions (
    case_id                 TEXT NOT NULL,
    firm_id                 TEXT NOT NULL,
    question_id             TEXT NOT NULL CHECK (question_id GLOB 'Q-*'),
    seq                     INTEGER NOT NULL CHECK (seq > 0),
    question                TEXT NOT NULL CHECK (length(trim(question)) > 0),
    purpose                 TEXT NOT NULL CHECK (length(trim(purpose)) > 0),
    finding_ids_json        TEXT NOT NULL CHECK (json_valid(finding_ids_json) AND json_type(finding_ids_json) = 'array'
                                                 AND json_array_length(finding_ids_json) > 0),
    transaction_ids_json    TEXT NOT NULL CHECK (json_valid(transaction_ids_json) AND json_type(transaction_ids_json) = 'array'
                                                 AND json_array_length(transaction_ids_json) > 0),
    presentation_fixes_json TEXT NOT NULL DEFAULT '[]' CHECK (json_valid(presentation_fixes_json)
                                                             AND json_type(presentation_fixes_json) = 'array'),
    status                  TEXT NOT NULL DEFAULT 'pending' CHECK (status IN ('pending', 'answered', 'withdrawn')),
    answer_text             TEXT,
    answered_at             TEXT CHECK (answered_at IS NULL OR answered_at LIKE '____-__-__T__:__:__%Z'),
    created_at              TEXT NOT NULL CHECK (created_at LIKE '____-__-__T__:__:__%Z'),
    CHECK ((status = 'answered') = (answer_text IS NOT NULL AND answered_at IS NOT NULL)),
    CHECK (answer_text IS NULL OR length(trim(answer_text)) > 0),
    PRIMARY KEY (case_id, question_id),
    UNIQUE (case_id, seq),
    FOREIGN KEY (case_id, firm_id) REFERENCES cases (id, firm_id) ON DELETE CASCADE
) STRICT;

-- At most one pending question per case (Stage 4 W1).
CREATE UNIQUE INDEX questions_one_pending_uq ON questions (case_id) WHERE status = 'pending';

-- Confirmations ------------------------------------------------------------------------
-- Structured client confirmations; append-only (the latest per finding counts).

CREATE TABLE confirmations (
    case_id           TEXT NOT NULL,
    firm_id           TEXT NOT NULL,
    seq               INTEGER NOT NULL CHECK (seq > 0),
    finding_id        TEXT NOT NULL CHECK (finding_id GLOB 'F[0-9]*'),
    proposed_category TEXT NOT NULL CHECK (proposed_category IN (
                          'Salary / Pension', 'Business / Professional Receipts', 'Rent Received',
                          'Interest – Savings Bank', 'Interest – FD / RD / Others', 'Dividend',
                          'Sale / Redemption of Investments', 'Income Tax Refund',
                          'Loans Received / Repayment of Loans Given', 'Gifts / Receipts from Non-relatives',
                          'Investments – Tax-saving', 'Investments – Others', 'Insurance – Health',
                          'Loan EMI / Repayment', 'Loans Given', 'Tax Payments', 'Donations',
                          'Credit Card Payments', 'Rent Paid', 'Business / Professional Expenses',
                          'Self Transfer', 'Family Transfer', 'Cash Withdrawal', 'Cash Deposit',
                          'Personal Expenses', 'Bank Charges', 'Reversals / Refunds', 'Others – Needs Review')),
    response          TEXT NOT NULL CHECK (response IN ('confirmed', 'denied', 'unsure')),
    created_at        TEXT NOT NULL CHECK (created_at LIKE '____-__-__T__:__:__%Z'),
    PRIMARY KEY (case_id, seq),
    FOREIGN KEY (case_id, firm_id) REFERENCES cases (id, firm_id) ON DELETE CASCADE
) STRICT;

CREATE TRIGGER confirmations_append_only
BEFORE UPDATE ON confirmations
BEGIN
    SELECT RAISE(ABORT, 'confirmations are append-only');
END;

-- Document requests and documents ----------------------------------------------------------

CREATE TABLE document_requests (
    id         TEXT PRIMARY KEY CHECK (length(id) = 36),
    case_id    TEXT NOT NULL,
    firm_id    TEXT NOT NULL,
    key        TEXT NOT NULL CHECK (length(key) > 0 AND key NOT GLOB '*[^a-z0-9_]*'),
    label      TEXT NOT NULL CHECK (length(trim(label)) > 0),
    status     TEXT NOT NULL DEFAULT 'requested' CHECK (status IN ('requested', 'received', 'waived')),
    source     TEXT NOT NULL CHECK (source IN ('rules', 'ca')),
    created_at TEXT NOT NULL CHECK (created_at LIKE '____-__-__T__:__:__%Z'),
    updated_at TEXT NOT NULL CHECK (updated_at LIKE '____-__-__T__:__:__%Z'),
    UNIQUE (case_id, key),
    UNIQUE (id, case_id),
    FOREIGN KEY (case_id, firm_id) REFERENCES cases (id, firm_id) ON DELETE CASCADE
) STRICT;

CREATE TABLE documents (
    id           TEXT PRIMARY KEY CHECK (length(id) = 36),
    case_id      TEXT NOT NULL,
    firm_id      TEXT NOT NULL,
    request_id   TEXT,
    kind         TEXT NOT NULL CHECK (kind IN ('bank_statement', 'supporting', 'workbook')),
    -- Relative path under the private storage root, generated by the server and
    -- confined to this firm's and case's directory.
    storage_key  TEXT NOT NULL UNIQUE
                 CHECK (substr(storage_key, 1, 74) = firm_id || '/' || case_id || '/'
                        AND length(storage_key) > 74
                        AND instr(storage_key, '..') = 0 AND instr(storage_key, '\') = 0
                        AND instr(storage_key, ':') = 0 AND instr(substr(storage_key, 75), '/') = 0),
    display_name TEXT NOT NULL CHECK (length(trim(display_name)) > 0),
    content_type TEXT NOT NULL CHECK (length(content_type) > 0),
    size_bytes   INTEGER NOT NULL CHECK (size_bytes > 0),
    sha256       TEXT NOT NULL CHECK (length(sha256) = 64 AND sha256 NOT GLOB '*[^0-9a-f]*'),
    status       TEXT NOT NULL DEFAULT 'stored' CHECK (status IN ('stored', 'rejected', 'superseded')),
    uploaded_by  TEXT NOT NULL CHECK (uploaded_by IN ('client', 'ca', 'system')),
    created_at   TEXT NOT NULL CHECK (created_at LIKE '____-__-__T__:__:__%Z'),
    CHECK (kind <> 'workbook' OR uploaded_by = 'system'),
    CHECK (kind = 'supporting' OR request_id IS NULL),
    UNIQUE (case_id, kind, sha256),
    FOREIGN KEY (case_id, firm_id) REFERENCES cases (id, firm_id) ON DELETE CASCADE,
    -- A document can only fulfil a request of its own case.
    FOREIGN KEY (request_id, case_id) REFERENCES document_requests (id, case_id)
) STRICT;

CREATE INDEX documents_case_kind_idx ON documents (case_id, kind);

-- E-mail outbox ----------------------------------------------------------------------------
-- Every notification is queued here first. The idempotency key prevents duplicates.

CREATE TABLE email_outbox (
    id                  TEXT PRIMARY KEY CHECK (length(id) = 36),
    idempotency_key     TEXT NOT NULL UNIQUE CHECK (length(idempotency_key) > 0),
    firm_id             TEXT REFERENCES firms (id),
    case_id             TEXT,
    template            TEXT NOT NULL CHECK (length(template) > 0),
    recipient           TEXT NOT NULL CHECK (recipient LIKE '%_@_%'),
    subject             TEXT NOT NULL CHECK (length(subject) > 0),
    body_text           TEXT,
    status              TEXT NOT NULL DEFAULT 'pending'
                        CHECK (status IN ('pending', 'simulated', 'sent', 'failed', 'dead', 'superseded')),
    attempts            INTEGER NOT NULL DEFAULT 0 CHECK (attempts >= 0),
    next_attempt_at     TEXT CHECK (next_attempt_at IS NULL OR next_attempt_at LIKE '____-__-__T__:__:__%Z'),
    last_error          TEXT,
    provider_message_id TEXT,
    created_at          TEXT NOT NULL CHECK (created_at LIKE '____-__-__T__:__:__%Z'),
    updated_at          TEXT NOT NULL CHECK (updated_at LIKE '____-__-__T__:__:__%Z'),
    sent_at             TEXT CHECK (sent_at IS NULL OR sent_at LIKE '____-__-__T__:__:__%Z'),
    CHECK (case_id IS NULL OR firm_id IS NOT NULL),
    CHECK ((status IN ('sent', 'simulated')) = (sent_at IS NOT NULL)),
    FOREIGN KEY (case_id, firm_id) REFERENCES cases (id, firm_id)
) STRICT;

CREATE INDEX email_outbox_due_idx ON email_outbox (status, next_attempt_at);

-- Audit events ------------------------------------------------------------------------------
-- Append-only security history. details_json must not contain personal or financial data.

CREATE TABLE audit_events (
    id           TEXT PRIMARY KEY CHECK (length(id) = 36),
    firm_id      TEXT REFERENCES firms (id),
    case_id      TEXT,
    actor_kind   TEXT NOT NULL CHECK (actor_kind IN ('ca', 'client', 'system', 'admin')),
    actor_id     TEXT,
    action       TEXT NOT NULL CHECK (length(action) > 0),
    details_json TEXT NOT NULL DEFAULT '{}' CHECK (json_valid(details_json) AND json_type(details_json) = 'object'),
    ip_hash      TEXT CHECK (ip_hash IS NULL OR (length(ip_hash) = 64 AND ip_hash NOT GLOB '*[^0-9a-f]*')),
    created_at   TEXT NOT NULL CHECK (created_at LIKE '____-__-__T__:__:__%Z'),
    CHECK (case_id IS NULL OR firm_id IS NOT NULL),
    FOREIGN KEY (case_id, firm_id) REFERENCES cases (id, firm_id)
) STRICT;

CREATE INDEX audit_events_firm_idx ON audit_events (firm_id, created_at);
CREATE INDEX audit_events_case_idx ON audit_events (case_id, created_at);

CREATE TRIGGER audit_events_no_update
BEFORE UPDATE ON audit_events
BEGIN
    SELECT RAISE(ABORT, 'audit events are append-only');
END;

CREATE TRIGGER audit_events_no_delete
BEFORE DELETE ON audit_events
BEGIN
    SELECT RAISE(ABORT, 'audit events are append-only');
END;
